      else{
        m=html.match(new RegExp('"'+k+'"\\s*:\\s*([^,\\s}]+)'));
        vals[k]=m?String(m[1]).replace(/"/g,''):'';
      }
    }
    if(!vals.url||!vals.sign){return '';}
    var parts=[],kk;
    for(kk in vals){
      if(vals.hasOwnProperty(kk)){parts.push(kk+'='+encodeURIComponent(vals[kk]));}
    }
    var hd={};
    hd['User-Agent']='Mozilla/5.0 (Linux; U; Android 10) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/100.0.4896.58 Mobile Safari/537.36';
