    hd['User-Agent']='Mozilla/5.0 (Linux; U; Android 10) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/100.0.4896.58 Mobile Safari/537.36';
    hd['Accept']='application/json, text/javascript, */*; q=0.01';
    hd['x-requested-with']='XMLHttpRequest';
    hd['content-type']='application/x-www-form-urlencoded; charset=UTF-8';
    hd['origin']='https://bcshuku.com';
    hd['referer']=base;
    var resp=J.post('https://bcshuku.com/conapi.php',parts.join('&'),hd);
