    var html=String(J.ajax(url));
    var cv='';
    var tags=html.match(/<img[^>]*>/gi)||[];
    for(var t=0;t<tags.length;t++){
      var sm=tags[t].match(/src="([^"]+)"/i);
      if(sm&&sm[1].indexOf('http')===0&&sm[1].indexOf('${')<0){
        if(sm[1].indexOf('/img/0')<0){cv=sm[1];break;}
      }
